"""
martianbook.renderer
--------------------
Renders a MartianReport into a MartianBook HTML document.

Features:
- Light / dark mode with system preference detection + manual toggle
- Martian logo embedded in header for branding
- Syntax-highlighted code blocks (highlight.js inlined)
- Collapsible cells with smooth animation
- Artifact image previews embedded as base64
- Section grouping with visual dividers
- Clean CSS variable theming — swap entire palette in one place

Author: Andrew Garcia
"""

from __future__ import annotations

import base64
import html
import os

from martianbook.core.schema import MartianReport, Status
from martianbook.core.serialization import to_json

# ---------------------------------------------------------------------------
# Embedded logo (base64)
# ---------------------------------------------------------------------------

_LOGO_B64 = ""
_LOGO_URI = f"data:image/svg+xml;base64,{_LOGO_B64}"


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def _file_exists(path: str) -> bool:
    return os.path.isfile(path)


def _embed_image(path: str, fmt: str) -> str:
    try:
        with open(path, "rb") as f:
            data = base64.b64encode(f.read()).decode("ascii")
        mime = {
            "png":  "image/png",
            "jpg":  "image/jpeg",
            "jpeg": "image/jpeg",
            "svg":  "image/svg+xml",
        }.get(fmt, "image/png")
        return f'<img class="artifact-img" src="data:{mime};base64,{data}" alt="{os.path.basename(path)}" />'
    except Exception:
        return ""


# ---------------------------------------------------------------------------
# Main render entry point
# ---------------------------------------------------------------------------

def render_html(report: MartianReport) -> str:
    m     = report.mission
    cells = "\n".join(
        _render_cell(report, node)
        for node in sorted(report.execution, key=lambda n: n.call_order)
    )

    return f"""<!DOCTYPE html>
<html lang="en" data-theme="dark">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>MartianBook — {html.escape(m.entry_point)}</title>
<style>{_CSS}</style>
</head>
<body>

<header>
  <div class="header-inner">
    <div class="header-left">
      <img class="logo-img" src="{_LOGO_URI}" alt="Martian logo" />
      <span class="logo-text">MartianBook</span>
    </div>
    <div class="header-center">
      <span class="mission-tag">{html.escape(m.entry_point)}</span>
      <span class="mission-tag">{html.escape(m.environment.language)} {html.escape(m.environment.language_version)}</span>
      <span class="mission-tag">{m.duration_ms:.1f}ms</span>
      <span class="mission-tag status-{m.status.value}">{m.status.value}</span>
    </div>
    <div class="header-right">
      <button class="theme-toggle" onclick="toggleTheme()" title="Toggle light/dark mode">
        <span class="theme-icon">◐</span>
      </button>
    </div>
  </div>
</header>

<main>
  {_render_mission_bar(report)}
  <div class="cells">
    {cells}
  </div>
</main>

<script>{_JS}</script>
</body>
</html>"""


def _render_mission_bar(report: MartianReport) -> str:
    m = report.mission
    fns   = len(report.execution)
    arts  = len(report.artifacts)
    excs  = len(report.exceptions)
    secs  = len(report.sections)

    stats = f"{fns} functions &nbsp;·&nbsp; {arts} artifacts &nbsp;·&nbsp; {excs} exceptions"
    if secs:
        stats += f" &nbsp;·&nbsp; {secs} sections"

    return f"""<div class="mission-bar">
  <span class="mission-id">{html.escape(m.id)}</span>
  <span class="mission-stats">{stats}</span>
</div>"""


def _render_cell(report: MartianReport, node) -> str:
    status_class = f"status-{node.status.value}"
    depth_px     = node.depth * 28
    icon         = "✓" if node.status == Status.SUCCESS else "✗"

    # --- Text block (docstring) ---
    text_block = ""
    if node.text:
        text_block = f'<div class="block block-text">{html.escape(node.text)}</div>'

    # --- Code block ---
    code_block = ""
    if node.source_code:
        code = html.escape(node.source_code)
        code_block = f"""<div class="block block-code">
  <div class="block-label">source</div>
  <pre><code class="language-python">{code}</code></pre>
</div>"""

    # --- Output block ---
    output_parts = []
    if node.args:
        args_str = ", ".join(f"{k}={v}" for k, v in node.args.items())
        output_parts.append(
            f'<div class="output-args">called with: {html.escape(args_str)}</div>'
        )
    if node.stdout:
        lines = "\n".join(html.escape(l) for l in node.stdout)
        output_parts.append(f'<div class="output-stdout"><pre>{lines}</pre></div>')
    if node.stderr:
        lines = "\n".join(html.escape(l) for l in node.stderr)
        output_parts.append(f'<div class="output-stderr"><pre>{lines}</pre></div>')
    if node.ret:
        r = node.ret
        if r.shape:
            ret_str = f"{r.type_name}[{'×'.join(str(d) for d in r.shape)}]"
        elif r.preview:
            ret_str = r.preview
        else:
            ret_str = r.type_name
        output_parts.append(
            f'<div class="output-return"><span class="ret-arrow">→</span> {html.escape(ret_str)}</div>'
        )

    output_block = ""
    if output_parts:
        output_block = f"""<div class="block block-output">
  <div class="block-label">output</div>
  {"".join(output_parts)}
</div>"""

    # --- Artifact blocks ---
    artifact_blocks = ""
    for art_id in node.artifact_ids:
        art = report.get_artifact(art_id)
        if art:
            name  = html.escape(art.label or art.path.split("/")[-1])
            atype = html.escape(art.type.value)
            img   = ""
            if art.format in ("png", "jpg", "jpeg", "svg") and _file_exists(art.path):
                img = _embed_image(art.path, art.format)
            artifact_blocks += f"""<div class="block block-artifact">
  <div class="block-label">artifact · {atype}</div>
  {img}
  <div class="artifact-meta">📎 {name} &nbsp;<span class="artifact-path">{html.escape(art.path)}</span></div>
</div>"""

    # --- Exception block ---
    exc_block = ""
    if node.exception_id:
        exc = report.get_exception(node.exception_id)
        if exc:
            exc_block = f"""<div class="block block-exception">
  <div class="block-label">exception</div>
  <div class="exc-type">{html.escape(exc.type_name)}: {html.escape(exc.message)}</div>
  <pre class="exc-traceback">{html.escape(exc.traceback)}</pre>
</div>"""

    # --- Section badge ---
    section_badge = ""
    if node.section:
        section_badge = f'<span class="section-badge">{html.escape(node.section)}</span>'

    # --- Timing badge ---
    timing = f'<span class="cell-timing">{node.duration_ms:.1f}ms</span>'

    # --- Children indicator ---
    children_badge = ""
    if node.children:
        children_badge = f'<span class="children-badge">{len(node.children)} child{"ren" if len(node.children) > 1 else ""}</span>'

    return f"""<div class="cell {status_class}" style="margin-left:{depth_px}px" data-id="{node.id}">
  <div class="cell-header" onclick="toggleCell(this)">
    <span class="cell-status-icon">{icon}</span>
    <span class="cell-name">{html.escape(node.name)}</span>
    <span class="cell-module">{html.escape(node.module)}:{node.line_start}</span>
    {section_badge}
    {children_badge}
    {timing}
    <span class="cell-chevron">▾</span>
  </div>
  <div class="cell-body">
    {text_block}
    {code_block}
    {output_block}
    {artifact_blocks}
    {exc_block}
  </div>
</div>"""


